    "ch5_s01_four_fronts_converge": {
        "id": "ch5_s01_four_fronts_converge",
        "title": "四條異常指向同一處",
        "chapter": 5,
        "chapterOrder": 1,
        "stageClass": "town_scene",
        "background": "civic room with four route reports, patient records, and damaged equipment arranged around one map",
        "worldState": "Chapter 5 opening; fire, ice, thunder, and poison fronts now peak on one rhythm",
        "viewpoint": "protagonist_limited",
        "knowledgeBoundary": null,
        "participantsRaw": "town scholar, Mia, blacksmith, village elder",
        "entry": "the exposed ruin-channel survey is placed beside four current route reports",
        "exit": "four-front regional canvas and required preparation open",
        "objective": "prove whether four regional hazards are expressions of one mountain pressure line",
        "inputsRaw": "Chapter 4 four-channel hypothesis; ruin survey; patient and equipment records",
        "outputsRaw": "Elemental Lord route hypothesis; role division among Mia, 伊萊, blacksmith, and elder",
        "assetNotes": "reuse civic background; no new NPC, affinity, or material introduced",
        "beats": [
            {
                "order": 1,
                "condition": "any",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "四張地圖壓在遺跡拓圖四周。火線焦痕、冰層裂口、雷擊金屬與毒斑病例各自不同，位置卻正好沿著四條受損刻槽向山裡靠攏。"
            },
            {
                "order": 2,
                "condition": "any",
                "beat": "enter",
                "actorId": "town_scholar",
                "expression": null,
                "text": "Town scholar, Mia, blacksmith and elder enter around the evidence table.",
                "actorIds": [
                    "town_scholar",
                    "herbalist",
                    "blacksmith",
                    "village_elder"
                ],
                "stageAction": "enter"
            },
            {
                "order": 3,
                "condition": "any",
                "beat": "speaker",
                "actorId": "town_scholar",
                "expression": "guarded",
                "text": "四處回報的時間對不上同一場地震，位置卻都沿著遺跡的刻槽。先別把它們當成四個源頭；我們得去現場確認這些力量最後流向哪裡。"
            },
            {
                "order": 4,
                "condition": "any",
                "beat": "speaker",
                "actorId": "herbalist",
                "expression": "guarded",
                "text": "症狀會輪替。先灼熱，再失溫，接著抽搐，最後出現毒性麻痺。現在還分散在人身上，不能假設永遠如此。"
            },
            {
                "order": 5,
                "condition": "any",
                "beat": "speaker",
                "actorId": "blacksmith",
                "expression": "neutral",
                "text": "裝備也照這順序壞。先軟、再脆、再被雷沿著裂口走一遍，最後連皮帶都發黑。"
            },
            {
                "order": 6,
                "condition": "any",
                "beat": "speaker",
                "actorId": "village_elder",
                "expression": "grieving",
                "text": "遠征時也看過。當時我們只顧著一處一處打過去，以為麻煩變多代表快到源頭。"
            },
            {
                "order": 7,
                "condition": "any",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "老人把四條線延長。它們沒有停在各自的區域，而是在山邊同一處尚未標名的壓力帶交會。"
            },
            {
                "order": 8,
                "condition": "second_run",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "你記得交會處會產生第一塊四象裂片，卻不能拿尚未發生的事說服眾人。這一次，每種殘留都會留下可比較的處理紀錄。"
            },
            {
                "order": 9,
                "condition": "any",
                "beat": "speaker",
                "actorId": "herbalist",
                "expression": "resolute",
                "text": "先準備能準備的。任何人接觸殘留都要記時間、溫度和症狀，不准只寫「撐得住」。"
            },
            {
                "order": 10,
                "condition": "any",
                "beat": "exit",
                "actorId": null,
                "expression": null,
                "text": "Open four-front routes, advanced forge preparation, and evidence-return requirements."
            }
        ]
    },
